public static int RomanToInt(string s)
{
    int total = 0;
    int prevValue = 0;

    // Iterate backwards to handle subtractive logic easily
    for (int i = s.Length - 1; i >= 0; i--)
    {
        int currentValue = GetValue(s[i]);

        if (currentValue < prevValue)
        {
            total -= currentValue;
        }
        else
        {
            total += currentValue;
        }

        prevValue = currentValue;
    }

    return total;
}

