        // Regex matches runs of letters, digits, or apostrophes
        // \w includes underscores; to be precise to the requirement: [a-zA-Z0-9']
        // However, \w is standard for "word characters". 
        // Using a character class to strictly follow "letters, digits or apostrophes".
        MatchCollection matches = Regex.Matches(text, @"[a-zA-Z0-9']+");

