    int low = 0;
    int high = sorted.Length - 1;
    int result = -1;

    while (low <= high)
    {
        int mid = low + (high - low) / 2;

        if (sorted[mid] == target)
        {
            result = mid;
            high = mid - 1; // Continue searching left to find the first occurrence
        }
        else if (sorted[mid] < target)
        {
            low = mid + 1;
        }
        else
        {
            high = mid - 1;
        }
    }

    return result;
}
