public static class StringExtensions
{
    public static string ToSnakeCase(string name)
    {
        if (string.IsNullOrEmpty(name))
        {
            return name;
        }

        StringBuilder result = new StringBuilder();
        int length = name.Length;

        for (int i = 0; i < length; i++)
        {
            char current = name[i];

            if (i > 0 && char.IsUpper(current))
            {
                char prev = name[i - 1];
                bool prevIsUpper = char.IsUpper(prev);
                bool nextIsLower = (i + 1 < length) && char.IsLower(name[i + 1]);

                // Case 1: Transition from lower to upper (e.g., 'aB' -> 'a_B')
                // Case 2: Transition from upper to upper followed by lower (e.g., 'HB' in 'HTTPResponse' -> 'HTTP_Response')
                if (!prevIsUpper || nextIsLower)
                {
                    result.Append('_');
                }
            }

            result.Append(char.ToLowerInvariant(current));
        }

        return result.ToString();
    }
